import re

def roman_to_int(s: str) -> int:
    # Canonical Roman numerals from 1 to 3999
    pattern = r"^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$"

    if not isinstance(s, str) or not s or not re.match(pattern, s):
        raise ValueError(f"Invalid Roman numeral: {s!r}")

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_val = 0
    for char in reversed(s):
        curr_val = roman_map[char]
        if curr_val < prev_val:
            total -= curr_val
        else:
            total += curr_val
            prev_val = curr_val

    return total
